1	<script lang="ts">
2		import Accordion from "./shared/Accordion.svelte";
3		import { Block } from "@gradio/atoms";
4		import { StatusTracker } from "@gradio/statustracker";
5	
6		import { BaseColumn } from "@gradio/column";
7		import { Gradio } from "@gradio/utils";
8		import type { SharedProps } from "@gradio/utils";
9	
10		import type { AccordionProps, AccordionEvents } from "./types";
11	
12		let props = $props();
13		class AccordionGradio extends Gradio<AccordionEvents, AccordionProps> {
14			set_data(data: Partial<object & SharedProps>): void {
15				if ("open" in data && data.open) {
16					this.dispatch("gradio_expand");
17				}
18				super.set_data(data);
19				this.shared.loading_status.status = "complete";
20			}
21		}
22		const gradio = new AccordionGradio(props);
23	
24		let label = $derived(gradio.shared.label || "");
25	
26		let visibility: boolean | "hidden" = $derived(
27			gradio.shared.visible === true ? true : "hidden"
28		);
29	</script>
30	
31	<Block
32		elem_id={gradio.shared.elem_id}
33		elem_classes={gradio.shared.elem_classes}
34		visible={visibility}
35	>
36		{#if gradio.shared.loading_status}
37			<StatusTracker
38				autoscroll={gradio.shared.autoscroll}
39				i18n={gradio.i18n}
40				{...gradio.shared.loading_status}
41			/>
42		{/if}
43	
44		<Accordion
45			{label}
46			open={gradio.props.open}
47			onexpand={() => {
48				gradio.dispatch("expand");
49				gradio.dispatch("gradio_expand");
50			}}
51			oncollapse={() => gradio.dispatch("collapse")}
52		>
53			<BaseColumn>
54				<slot />
55			</BaseColumn>
56		</Accordion>
57	</Block>
