1	import { describe, test, expect, afterEach } from "vitest";
2	import { render, cleanup } from "./render";
3	
4	const loading_status = {
5		status: "complete",
6		queue_position: null,
7		queue_size: null,
8		eta: null,
9		message: null
10	};
11	
12	export interface SharedPropTestConfig {
13		/** The Svelte component to test */
14		component: any;
15		/** Minimum props required to render the component without errors */
16		base_props: Record<string, any>;
17		/** Display name for test output */
18		name: string;
19		/**
20		 * Some components don't render labels (e.g. HTML, Markdown).
21		 * Set to false to skip label-related tests.
22		 * @default true
23		 */
24		has_label?: boolean;
25		/**
26		 * Whether the component renders validation_error text.
27		 * Not all components support this. Set to false to skip.
28		 * @default true
29		 */
30		has_validation_error?: boolean;
31	}
32	
33	export function run_shared_prop_tests(config: SharedPropTestConfig): void {
34		const {
35			component,
36			base_props,
37			name,
38			has_label = true,
39			has_validation_error = true
40		} = config;
41	
42		const label = "Test Label";
43	
44		function make_props(
45			overrides: Record<string, any> = {}
46		): Record<string, any> {
47			return {
48				...base_props,
49				loading_status,
50				label,
51				...overrides
52			};
53		}
54	
55		describe(`${name}: shared props`, () => {
56			afterEach(() => cleanup());
57	
58			test("elem_id is applied to the wrapper", async () => {
59				const { container } = await render(
60					component,
61					make_props({ elem_id: "my-test-id" })
62				);
63				const el = container.querySelector("#my-test-id");
64				expect(el).not.toBeNull();
65			});
66	
67			test("elem_classes are applied to the wrapper", async () => {
68				const { container } = await render(
69					component,
70					make_props({ elem_classes: ["my-test-class"] })
71				);
72				const el = container.querySelector(".my-test-class");
73				expect(el).not.toBeNull();
74			});
75	
76			test("visible: true renders the component", async () => {
77				const { container } = await render(
78					component,
79					make_props({ visible: true })
80				);
81				const el = container.querySelector(".block");
82				expect(el).not.toBeNull();
83			});
84	
85			test("visible: 'hidden' hides the component but keeps it in the DOM", async () => {
86				const result = await render(
87					component,
88					make_props({ visible: "hidden", elem_id: "hidden-test" })
89				);
90	
91				const el = result.container.querySelector("#hidden-test");
92				expect(el).not.toBeNull();
93				expect(el).not.toBeVisible();
94			});
95	
96			test("visible: false removes the component from the DOM", async () => {
97				const result = await render(
98					component,
99					make_props({ visible: false, elem_id: "gone-test" })
100				);
101	
102				const el = result.container.querySelector("#gone-test");
103				expect(el).toBeNull();
104			});
105	
106			if (has_label) {
107				test("label text is rendered", async () => {
108					const result = await render(
109						component,
110						make_props({ label: "My Custom Label", show_label: true })
111					);
112					const el = result.getByText("My Custom Label");
113					expect(el).toBeTruthy();
114				});
115	
116				test("show_label: true makes the label visible", async () => {
117					const result = await render(
118						component,
119						make_props({ label: "Visible Label", show_label: true })
120					);
121					const el = result.getByText("Visible Label");
122					expect(el).toBeVisible();
123				});
124	
125				test("show_label: false hides the label visually but keeps it in the DOM", async () => {
126					const result = await render(
127						component,
128						make_props({ label: "Hidden Label", show_label: false })
129					);
130					const el = result.getByText("Hidden Label");
131					// The label remains in the DOM for screen readers via sr-only.
132					// sr-only uses clip/1px dimensions rather than display:none,
133					// so toBeVisible() won't catch it. We check the class directly.
134					expect(el.closest("[data-testid='block-info']")).toHaveClass("sr-only");
135				});
136			}
137	
138			if (has_validation_error) {
139				test("validation_error displays error text", async () => {
140					const result = await render(
141						component,
142						make_props({ validation_error: "This field is required" })
143					);
144					const el = result.getByText("This field is required");
145					expect(el).toBeTruthy();
146				});
147			}
148		});
149	}
